css_snippet:
body {
  font-family: 'Open Sans', Arial, sans-serif;
  font-size: 16px;
  /* Normalize x-height relative to 'Open Sans' aspect value (approx 0.52 for 16px). */
  /* This is the base aspect value we want to maintain visually. */
  font-size-adjust: 0.52;
}

h1 {
  font-family: 'Merriweather', Georgia, serif;
  font-size: 2.5em;
  /* Apply the same desired x-height ratio to headings for consistency. */
  /* 'Merriweather' will be resized to visually match the x-height proportion of 0.52. */
  font-size-adjust: 0.52;
}

/* Example: Ensuring a fallback font like Arial visually scales well if 'Custom Web Font' fails */
p {
  font-family: 'Custom Web Font', Arial, sans-serif;
  font-size: 1rem;
  /* If 'Custom Web Font' fails to load, Arial will display with an adjusted font-size
     to maintain the visual x-height consistency specified by 0.52, improving UX. */
  font-size-adjust: 0.52;
}
